            return defaults;
        }

        var parsed = rawValue
            .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(domain => !string.IsNullOrWhiteSpace(domain))
            .ToArray();

        return parsed.Length > 0 ? parsed : defaults;
    }

